    "explanation": "Rotting is a biological decomposition process driven by microbial enzymes that breaks down organic molecules into fundamentally new substances with distinct odors and chemical properties. Dissolving sugar, melting ice cream (a phase transition), and cutting paper alter only spatial distribution, physical state, or macroscopic shape without rearranging chemical bonds.",
